static void statement(LexState *ls);
static void expr(LexState *ls);          /* prototypes = recursive non-terminals */
static int testnext(LexState *ls, int tok) {
    if (ls->t != tok) return 0;          /* lookahead without consuming */
    next(ls);                            /* consume and advance */
    return 1;
}

static void ifstat(LexState *ls) {
    expect(ls, TK_IF); expr(ls); expect(ls, TK_THEN);
    statement(ls);                       /* rule body = calls to other rules */
}
